<script>
const SHOTS = [
  {
    num: 1, label: "Shot 1 — open", role: "Hook / pattern interrupt",
    badgeBg: "#dde9f8", badgeColor: "#1a5fb4",
    darkBadgeBg: "#1a2d4a", darkBadgeColor: "#5b9cf0"
  },
  {
    num: 2, label: "Shot 2 — tension", role: "Amplify the problem or desire",
    badgeBg: "#fde8d8", badgeColor: "#c4511a",
    darkBadgeBg: "#3d1f0a", darkBadgeColor: "#f0875b"
  },
  {
    num: 3, label: "Shot 3 — reveal", role: "Introduce product / solution",
    badgeBg: "#d4f0e4", badgeColor: "#1a7a4a",
    darkBadgeBg: "#0d2e1e", darkBadgeColor: "#4ecf8a"
  },
  {
    num: 4, label: "Shot 4 — proof", role: "Benefit / social proof moment",
    badgeBg: "#fdefd0", badgeColor: "#8a5a00",
    darkBadgeBg: "#2e1f00", darkBadgeColor: "#f0be50"
  },
  {
    num: 5, label: "Shot 5 — close", role: "CTA + motif callback",
    badgeBg: "#e8d8f8", badgeColor: "#6a2fb4",
    darkBadgeBg: "#1e0d3a", darkBadgeColor: "#b07af0"
  }
];

const FIELDS = [
  { key: "scene",    label: "Scene / action",   full: true,  type: "textarea", ph: "What's physically happening on screen" },
  { key: "audio",    label: "Audio / VO",        full: false, type: "textarea", ph: "Spoken line or sound" },
  { key: "text",     label: "On-screen text",    full: false, type: "textarea", ph: "Caption or overlay" },
  { key: "motif",    label: "Motif appearance",  full: false, type: "input",    ph: "How the motif shows up" },
  { key: "product",  label: "Product in frame",  full: false, type: "input",    ph: "How product appears" },
  { key: "duration", label: "Duration (s)",      full: false, type: "input",    ph: "e.g. 3" }
];

const data = SHOTS.map(() => Object.fromEntries(FIELDS.map(f => [f.key, ""])));
let current = 0;
let exportOpen = false;
const darkMQ = window.matchMedia("(prefers-color-scheme: dark)");

function badgeBg(i)    { return darkMQ.matches ? SHOTS[i].darkBadgeBg    : SHOTS[i].badgeBg; }
function badgeText(i)  { return darkMQ.matches ? SHOTS[i].darkBadgeColor  : SHOTS[i].badgeColor; }

function buildCards() {
  const container = document.getElementById("cards");
  container.innerHTML = "";
  SHOTS.forEach((s, i) => {
    const card = document.createElement("div");
    card.className = "shot-card" + (i === current ? " visible active" : "");
    card.id = "card-" + i;
    card.setAttribute("role", "tabpanel");
    card.setAttribute("aria-label", s.label);

    let html = `
      <div class="card-header">
        <div class="badge" style="background:${badgeBg(i)};color:${badgeText(i)}">${s.num}</div>
        <div>
          <div class="card-label">${s.label}</div>
          <div class="card-role">${s.role}</div>
        </div>
      </div>
      <div class="card-fields">`;

    FIELDS.forEach(f => {
      html += `<div class="card-field${f.full ? " full" : ""}">
        <label for="f-${i}-${f.key}">${f.label}</label>`;
      const val = (data[i][f.key] || "").replace(/"/g, "&quot;");
      if (f.type === "textarea") {
        html += `<textarea id="f-${i}-${f.key}" rows="2" placeholder="${f.ph}"
          oninput="save(${i},'${f.key}',this.value)">${val}</textarea>`;
      } else {
        html += `<input type="text" id="f-${i}-${f.key}" placeholder="${f.ph}"
          value="${val}" oninput="save(${i},'${f.key}',this.value)">`;
      }
      html += `</div>`;
    });

    html += `</div>`;
    card.innerHTML = html;
    container.appendChild(card);
  });
}

function buildDots() {
  const row = document.getElementById("dot-row");
  row.innerHTML = "";
  SHOTS.forEach((s, i) => {
    const btn = document.createElement("button");
    btn.className = "dot" + (i === current ? " active" : "");
    btn.setAttribute("role", "tab");
    btn.setAttribute("aria-label", s.label);
    btn.setAttribute("aria-selected", i === current ? "true" : "false");
    btn.onclick = () => { current = i; refresh(); };
    row.appendChild(btn);
  });
}

function save(idx, key, val) {
  data[idx][key] = val;
  updateProgress();
  if (exportOpen) renderBrief();
}

function updateProgress() {
  const n = data.filter(d => d.scene && d.scene.trim()).length;
  document.getElementById("progress-pill").textContent = n + " / 5 filled";
}

function refresh() {
  SHOTS.forEach((_, i) => {
    const card = document.getElementById("card-" + i);
    if (!card) return;
    card.className = "shot-card" + (i === current ? " visible active" : "");
  });
  buildDots();
  document.getElementById("btn-prev").disabled = current === 0;
  document.getElementById("btn-next").disabled = current === 4;
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function prevShot() { if (current > 0) { current--; refresh(); } }
function nextShot() { if (current < 4) { current++; refresh(); } }

function buildBriefText() {
  const hook    = document.getElementById("t-hook").value.trim();
  const motif   = document.getElementById("t-motif").value.trim();
  const product = document.getElementById("t-product").value.trim();
  const cta     = document.getElementById("t-cta").value.trim();

  let out = "=== 5-SHOT HOOK BRIEF ===\n";

  if (hook || motif || product || cta) {
    out += "\nCONTINUITY THREADS\n";
    if (hook)    out += "  Opening hook: " + hook + "\n";
    if (motif)   out += "  Visual motif: " + motif + "\n";
    if (product) out += "  Product/object: " + product + "\n";
    if (cta)     out += "  CTA: " + cta + "\n";
  }

  SHOTS.forEach((s, i) => {
    const d = data[i];
    out += "\n--- " + s.label.toUpperCase() + " / " + s.role + " ---\n";
    if (d.scene)    out += "  Scene: "          + d.scene    + "\n";
    if (d.audio)    out += "  Audio/VO: "        + d.audio    + "\n";
    if (d.text)     out += "  On-screen text: "  + d.text     + "\n";
    if (d.motif)    out += "  Motif: "           + d.motif    + "\n";
    if (d.product)  out += "  Product: "         + d.product  + "\n";
    if (d.duration) out += "  Duration: "        + d.duration + "s\n";
  });

  out += "\n========================";
  return out;
}

function renderBrief() {
  document.getElementById("brief-text").value = buildBriefText();
}

function toggleExport() {
  exportOpen = !exportOpen;
  const area = document.getElementById("export-area");
  const btn  = document.getElementById("btn-export");
  if (exportOpen) {
    renderBrief();
    area.classList.add("visible");
    btn.textContent = "";
    btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg> Close`;
    setTimeout(() => area.querySelector("textarea").scrollIntoView({ behavior: "smooth", block: "nearest" }), 50);
  } else {
    area.classList.remove("visible");
    btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><rect x="8" y="2" width="8" height="4" rx="1" ry="1"/></svg> Export brief`;
  }
}

function copyBrief() {
  const text = buildBriefText();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => showToast("Copied to clipboard ✓")).catch(() => fallbackCopy(text));
  } else {
    fallbackCopy(text);
  }
}

function fallbackCopy(text) {
  const ta = document.getElementById("brief-text");
  ta.select();
  try {
    document.execCommand("copy");
    showToast("Copied ✓");
  } catch {
    showToast("Select the text above and copy manually");
  }
}

function downloadBrief() {
  const text = buildBriefText();
  const blob = new Blob([text], { type: "text/plain" });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement("a");
  a.href     = url;
  a.download = "hook-brief.txt";
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 500);
  showToast("hook-brief.txt saved ✓");
}

function showToast(msg) {
  const t = document.getElementById("toast");
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(t._timer);
  t._timer = setTimeout(() => t.classList.remove("show"), 2400);
}

// init
buildCards();
buildDots();
document.getElementById("btn-prev").disabled = true;

// re-color badges if color scheme flips
darkMQ.addEventListener("change", () => buildCards());
</script>
</body>
</html>

